import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 8 — High TPS, Performance & Capacity","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_08_High_TPS.md","filePath":"todo/study_plan/parts/Part_08_High_TPS.md"}'),o={name:"todo/study_plan/parts/Part_08_High_TPS.md"};function i(s,t,n,l,h,c){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="part-8-—-high-tps-performance-capacity" tabindex="-1">Part 8 — High TPS, Performance &amp; Capacity <a class="header-anchor" href="#part-8-—-high-tps-performance-capacity" aria-label="Permalink to &quot;Part 8 — High TPS, Performance &amp; Capacity&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 5 (shared with end of Part 7 and Part 9). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_8-high-tps-performance-capacity-—-topic-inventory" tabindex="-1">8 High TPS, Performance &amp; Capacity — topic inventory <a class="header-anchor" href="#_8-high-tps-performance-capacity-—-topic-inventory" aria-label="Permalink to &quot;8 High TPS, Performance &amp; Capacity — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Latency numbers every programmer should know (L1 → memory → SSD → network → cross-region)</td><td>🔴 💼 🎯</td><td>L</td><td>40 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Jeff Dean&#39;s &quot;Latency numbers every programmer should know&quot; · 💻 Warm-up: write latency cheat sheet from memory — L1, L2, RAM, SSD, HDD, intra-DC RTT, cross-region RTT (10 min)</td></tr><tr><td>2</td><td>Throughput math — RPS × payload, network bandwidth, storage growth</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Storage estimation — daily writes × retention × replication factor</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Profiling — async-profiler, JFR, perf</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>🎓 async-profiler GitHub README · 💻 Warm-up: run async-profiler on a small Java app, capture CPU profile, render flame graph (30 min)</td></tr><tr><td>5</td><td>Flame graphs — reading them</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Read/write ratio reasoning</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>Hot vs cold data, tiering</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Peak-to-average ratio (don&#39;t size for average)</td><td>🟠 💼 🎯</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>GC tuning intuition (without going overboard)</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Connection pool sizing (HikariCP — <code>pool size = ((cores × 2) + effective_spindle_count)</code>)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 6 HikariCP)</td></tr><tr><td>11</td><td>Thread pool sizing — Little&#39;s Law</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>P50 / P90 / P99 / P99.9 latency — tail latency matters more than average</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Gil Tene — &quot;How NOT to measure latency&quot; (~30 min, canonical)</td></tr><tr><td>13</td><td>Load testing — JMeter, Gatling, k6, Locust</td><td>🟠 💼</td><td>MP</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write k6 script with 10 VUs ramping to 100 over 30s against a local endpoint, read the p95 (30 min)</td></tr><tr><td>14</td><td>Async I/O, non-blocking</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Batching writes</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Pipelining requests (Redis pipelining, HTTP/2)</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Cache warm-up</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>Precomputation / materialization</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Read-path optimization (denormalization, fan-out on write)</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Write-path optimization (LSM trees, append-only logs)</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>Microbenchmarking — JMH, pitfalls</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Lock-free data structures</td><td>🟡</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>Off-heap memory</td><td>🟡</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~9.67 hrs</td><td>~0.9 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~26.17 hrs</td><td>~2.4 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~30.67 hrs</td><td>~2.8 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>Latency hierarchy (orders of magnitude):</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;L1 cache&lt;br/&gt;~1 ns&quot;] --&gt; B[&quot;L2 cache&lt;br/&gt;~4 ns&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;RAM&lt;br/&gt;~100 ns&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;SSD random read&lt;br/&gt;~150 µs&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;Intra-DC network&lt;br/&gt;~500 µs&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;HDD seek&lt;br/&gt;~10 ms&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G[&quot;Cross-region RTT&lt;br/&gt;~100 ms&quot;]</span></span></code></pre></div><blockquote><p>Each step is roughly 10-1000× slower than the previous. Internalize: RAM is 100,000× faster than HDD seek; intra-DC network is 1000× slower than RAM.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Estimate the storage requirement for a KYC platform processing 1M verifications/day, with 10KB metadata + 500KB images each, 3 replicas, 7-year retention. <ul><li><strong>Why asked:</strong> Back-of-envelope is senior-canonical. Math: 1M × (10KB + 500KB) = ~510GB/day. × 365 × 7 × 3 (replicas) = ~3.9PB. Round up for indices, indexes, audit logs: ~5PB. Tests fluency in unit conversion + planning.</li></ul></li><li><strong>Q:</strong> Your service has P99 latency of 200ms, but P50 is 30ms. Why does this matter more than the average? <ul><li><strong>Why asked:</strong> Tail latency understanding. P99 means 1% of users see 200ms — at 1M requests/day, that&#39;s 10K users with bad experience. Average hides this. Senior signal: discuss percentile-of-percentiles when fanning out (P99 of a service that fans out to 10 services = a much higher composite latency).</li></ul></li><li><strong>Q:</strong> Walk through Little&#39;s Law and apply it to size a thread pool. <ul><li><strong>Why asked:</strong> Operational depth. L = λW: concurrent requests = throughput × latency. If you want 100 RPS and each takes 200ms = 100 × 0.2 = 20 concurrent. Pool size ≈ 20 (plus headroom). Tests practical capacity reasoning.</li></ul></li><li><strong>Q:</strong> When does async I/O beat blocking I/O? When does it not? <ul><li><strong>Why asked:</strong> I/O-bound vs CPU-bound. Async wins when blocking time dominates (network calls, DB queries) — frees threads to do other work. Async loses or no-difference for CPU-bound work and for low-concurrency scenarios where blocking is simpler. Adds complexity (callback hell, harder debugging).</li></ul></li><li><strong>Q:</strong> Read this flame graph. What does the wide red bar at the bottom mean? <ul><li><strong>Why asked:</strong> Profiling literacy. Width = total samples in that stack frame; depth = call depth. A wide bar = hot path. Wide-and-red typically marks high CPU usage in that frame. Senior should identify hot paths in 30 seconds.</li></ul></li><li><strong>Q:</strong> Your endpoint hits 500 RPS but P99 jumps from 50ms to 5s above 400 RPS. What&#39;s happening? <ul><li><strong>Why asked:</strong> Capacity ceiling reasoning. Likely: thread pool saturation, queue buildup, GC pressure, or downstream rate limit. Diagnosis steps: check thread pool utilization, queue depth, GC log, downstream latency. Could be Little&#39;s Law violated (more concurrent in-flight than pool size allows → queueing).</li></ul></li><li><strong>Q:</strong> Read path vs write path optimization — give one example each from your KYC platform. <ul><li><strong>Why asked:</strong> Domain application. Read path: cache the verification status (fan-out on write to Redis cache). Write path: batch document uploads to S3 in 5MB chunks rather than per-image. Demonstrates platform-aware thinking.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Pool size of <code>cores × 2</code> — when is this rule wrong? <ul><li><strong>Gotcha:</strong> The rule applies to CPU-bound work. For I/O-bound work (DB calls, HTTP calls), pool size should be MUCH higher — Little&#39;s Law dictates it. Conversely, for highly parallel CPU work, even <code>cores × 2</code> is too many (context-switching overhead). Always derive from workload, not from the rule.</li></ul></li><li><strong>Q:</strong> Your microbenchmark says <code>String concatenation</code> takes 5ns. Production says 5µs. What&#39;s the gap? <ul><li><strong>Gotcha:</strong> JMH must run benchmarks in a forked JVM with warm-up + black-hole sink to prevent dead-code elimination. Without these, the JIT optimizes away the concatenation entirely → bogus number. Production-realistic numbers require representative workload + warm JIT.</li></ul></li><li><strong>Q:</strong> P99 of 50ms feels great. But when 10 microservices each have P99=50ms and you fan out to all of them, what&#39;s the resulting P99? <ul><li><strong>Gotcha:</strong> Higher than 50ms. Approximately P99^10 — the composite request hits at least one slow path. Roughly, expected slow-path probability = 1 - (0.99)^10 ≈ 10%. So composite P99 will be much closer to P99.9 of individual services. This is why tail latency compounds badly in fan-out architectures.</li></ul></li><li><strong>Q:</strong> You added a Redis cache to your hot read path. Latency dropped, but throughput didn&#39;t improve. Why? <ul><li><strong>Gotcha:</strong> Bottleneck moved, not removed. If reads were fast but writes were the bottleneck, the cache didn&#39;t help throughput. Or: the cache itself became the bottleneck (single Redis instance with too many connections). Or: cache warming is still happening (cold cache means many misses still hit the DB).</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Profiling + flame graph walkthrough</strong> (~3.5 hrs combined rows 4 + 5) — async-profiler in production-like setup, flame graph reading. Pair with a hot-path investigation against a real Spring Boot app.</li><li><strong>Latency budget design for the KYC platform</strong> (~2.5 hrs) — start with a 1-second SLO, decompose across SDK → orchestrator → 3 vendor calls → DB writes. Show where time goes; identify the bottleneck.</li><li><strong>Tail-latency analysis end-to-end</strong> (~2.5 hrs combined rows 12 + question about P99) — read Gil Tene&#39;s &quot;How NOT to measure latency&quot;, compute composite P99 under fan-out, design test for it.</li><li><strong>Little&#39;s Law applied to your thread pool sizing</strong> (~2 hrs row 11) — derive pool size for KYC verification orchestrator given vendor latencies and target RPS.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up performance exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Flame graph reading session</strong> (~60 min) — capture an async-profiler flame graph of a Spring Boot app under k6 load. Identify the top 3 hot methods. Add a SQL N+1 anti-pattern intentionally — re-capture, observe the new hot frames.</li><li><strong>Little&#39;s Law calculation drill</strong> (~30 min) — given 3 scenarios (200 RPS @ 50ms, 100 RPS @ 500ms, 1000 RPS @ 10ms), compute required concurrency. Pick a target thread pool size with 20% headroom.</li><li><strong>JMH benchmark of string concatenation styles</strong> (~60 min) — <code>+</code>, <code>StringBuilder</code>, <code>String.format</code>, <code>String.join</code>. Run with proper JMH boilerplate (warm-up + blackhole + forks). Read the percentiles, not the average.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Latency budget for KYC verification end-to-end</strong> (~90 min) — write up a 1-second SLO budget broken down by SDK upload, orchestrator decision, 3 vendor calls (face-match, liveness, OCR), DB writes, callback. Identify the slowest hop. Document mitigations.</li><li><strong>Design for 10× current traffic</strong> (~60 min) — pick your KYC platform&#39;s current scale, multiply by 10. Identify which bottlenecks appear first (vendor rate limits, DB connections, thread pool, queue depth). Outline 3 architectural changes.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~70 min for Part 8 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. L1 cache vs disk seek — order of magnitude difference?</strong> A. ~1 ns vs ~10 ms = 10,000,000× (ten million). Most latency budget goes to network and disk.</p><p><strong>Q. Little&#39;s Law in one sentence.</strong> A. Concurrent in-flight requests (L) = throughput (λ) × average latency (W). Use it to size pools: target_pool_size = target_RPS × average_latency.</p><p><strong>Q. P99 vs P99.9 — why both matter?</strong> A. P99 = 1% of users hit the slow path. At 1M req/day, that&#39;s 10K user-visible slow experiences. P99.9 catches the next layer — 0.1% = 1000 users. Fan-out architectures see composite percentiles way worse than individual.</p><p><strong>Q. Why is &quot;average latency&quot; misleading?</strong> A. A few slow outliers can pull the average up (or down) while hiding the actual user experience. Latency is heavily right-skewed; use percentiles, not means.</p><p><strong>Q. LSM tree vs B-tree — when each?</strong> A. LSM (Log-Structured Merge): write-heavy workloads (Cassandra, RocksDB, LevelDB) — append-only writes are fast, reads cost extra (merge from multiple SSTables). B-tree: read-heavy + balanced (Postgres, MySQL InnoDB).</p><p><strong>Q. JMH gotcha — what&#39;s a microbenchmark pitfall?</strong> A. The JIT can dead-code-eliminate trivial code (e.g., <code>x + 1</code> without using the result) → fake fast numbers. JMH solves this with <code>Blackhole.consume()</code>, forks, and proper warm-up phases.</p>`,32)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
